const items = $input.all();

// Extract JSON function
function extractJSON(text) {
  if (!text || typeof text !== 'string') {
    throw new Error('Invalid input: text must be a non-empty string');
  }

  try {
    // Remove markdown code blocks
    let cleaned = text
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/g, '')
      .trim();

    // Find JSON pattern (array or object)
    const arrayMatch = cleaned.match(/\[[\s\S]*\]/);
    const objectMatch = cleaned.match(/\{[\s\S]*\}/);

    let jsonStr;
    if (arrayMatch) {
      jsonStr = arrayMatch[0];
    } else if (objectMatch) {
      jsonStr = objectMatch[0];
    } else {
      jsonStr = cleaned;
    }

    // Parse JSON
    return JSON.parse(jsonStr);

  } catch (error) {
    throw new Error(`JSON extraction failed: ${error.message}`);
  }
}

// Process all items
const results = items.map((item, index) => {
  try {
    const inputText = item.json.text || item.json.body || item.json.content;
    const extracted = extractJSON(inputText);

    // If extracted is an array, flatten it
    if (Array.isArray(extracted)) {
      return extracted.map(obj => ({ json: obj }));
    } else {
