// This code works with the Merge node output

// Get all input items from the Merge node
const allItems = $input.all();

// Separate the data based on which input they came from
// Input 0: User resumes (from Postgres)
// Input 1: Job applications (from Combine1)

const userResumes = [];
const jobApplications = [];

// The Merge node passes through all items
// We need to identify which items are resumes and which are applications
allItems.forEach(item => {
  const data = item.json;

  // If it has 'Id' and 'ResumeUrl' properties, it's from the Users table
  if (data.Id && data.ResumeUrl && !data.job_id) {
    userResumes.push(data);
  }
  // If it has job_id and UserId, it's a job application
  else if (data.job_id && data.UserId !== undefined) {
    jobApplications.push(data);
  }
});

// Create a lookup map for quick access: UserId -> ResumeUrl
const resumeMap = {};
userResumes.forEach(user => {
  resumeMap[user.Id] = user.ResumeUrl;
});

// S3 bucket base URL
const baseUrl = 'https://hirethemnow-files.s3.us-east-1.amazonaws.com/';

// Update the resumeUrl in job applications
const updatedApplications = jobApplications.map(app => {
  // Check if we have a matching resume for this UserId
  if (resumeMap[app.UserId]) {
    return {
      ...app,
      resumeUrl: baseUrl + resumeMap[app.UserId]
    };
  }
  // If no match found, keep original
  return app;
});

// Return the updated applications
return updatedApplications.map(app => ({ json: app }));
